cypress_script:
describe('Numeric Input Field Validation', () => {
  it('should accept valid numeric input', () => {
    cy.visit('https://the-internet.herokuapp.com/inputs');
    cy.get('input[type="number"]').type('123');
    cy.get('input[type="number"]').should('have.value', '123');
  });
  it('should not change the URL when input is empty', () => {
    cy.visit('https://the-internet.herokuapp.com/inputs');
    cy.get('input[type="number"]').clear();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/inputs');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Numeric Input Field Validation', () => {
  test('should accept valid numeric input', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/inputs');
    await page.fill('input[type="number"]', '123');
    const value = await page.inputValue('input[type="number"]');
    expect(value).toBe('123');
  });
  test('should not change the URL when input is empty', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/inputs');
    await page.fill('input[type="number"]', '');
    expect(page.url()).toBe('https://the-internet.herokuapp.com/inputs');
  });
});
